 [STAThread]static void Main(){Application.SetHighDpiMode(HighDpiMode.PerMonitorV2);Directory.CreateDirectory("artifacts");var evidence=new Dictionary<string,object>();using var rsa=RSA.Create(3072);var identity=new Identity("http://127.0.0.1",Guid.NewGuid().ToString(),Guid.NewGuid().ToString(),rsa.ExportPkcs8PrivateKeyPem(),rsa.ExportSubjectPublicKeyInfoPem());
