 var sid=WindowsIdentity.GetCurrent().User!;var acl=SessionBroker.Security(sid);var rules=acl.GetAccessRules(true,true,typeof(SecurityIdentifier)).Cast<PipeAccessRule>().ToArray();Check(rules.Any(x=>x.IdentityReference.Value=="S-1-5-2"&&x.AccessControlType==AccessControlType.Deny),"Network pipe access denied");Check(!rules.Any(x=>x.IdentityReference.Value=="S-1-1-0"&&x.AccessControlType==AccessControlType.Allow),"No Everyone grant");evidence["ipcFramingAndAclChecks"]=true;
