 using(var bitmap=new Bitmap(1280,720)){using(var g=Graphics.FromImage(bitmap))g.Clear(Color.MediumSlateBlue);var process=Process.GetCurrentProcess();var cpu=process.TotalProcessorTime;var watch=Stopwatch.StartNew();long bytes=0;for(int i=0;i<20;i++){var jpeg=JpegEncoder.Encode(bitmap,new CaptureOptions(640,55,5));using var decoded=new Bitmap(new MemoryStream(jpeg));Check(decoded.Width==640&&decoded.Height==360,"Encoded dimensions");bytes+=jpeg.Length;}evidence["syntheticEncoding"]=new{frames=20,elapsedMs=watch.Elapsed.TotalMilliseconds,cpuMs=(process.TotalProcessorTime-cpu).TotalMilliseconds,totalBytes=bytes,memoryBytes=process.WorkingSet64,realScreen=false};}
