on.PointToScreen(new Point(50,20));var screen=Screen.PrimaryScreen.Bounds;await desktop.Apply(JsonSerializer.SerializeToElement(new{kind="move",x=(p.X-screen.Left)/(double)(screen.Width-1),y=(p.Y-screen.Top)/(double)(screen.Height-1),seq=2}),CancellationToken.None);await desktop.Apply(JsonSerializer.SerializeToElement(new{kind="button",button="left",down=true,seq=3}),CancellationToken.None);await Task.Delay(50);await desktop.Apply(JsonSerializer.SerializeToElement(new{kind="button",button="left",down=false,seq=4}),CancellationToken.None);await Task.Delay(120);Check(clicks==1,"Real SendInput click");await desktop.Revoke(CancellationToken.None);bool denied=false;try{await desktop.Apply(JsonSerializer.SerializeToElement(new{kind="text",text="denied",seq=5}),CancellationToken.None);}catch(UnauthorizedAccessException){denied=true;}Check(denied,"Input rejected after revocation");evidence["interactiveComponentValidated"]=true;evidence["realLoopbackEngine"]=await EngineLoopbackValidation.Run(form,target,panel,button)??new{notRequested=true};evidence["interactiveComponentValidated"]=true;evidence["interactiveChecks"]=new[]{"GDI capture of own window marker","JPEG decode","Arabic Unicode input in own textbox","Mouse click in own window","Post-revocation rejection"};}catch(Exception ex){failure=ex;}finally{form.Close();}};Application.Run(form);if(failure!=null){evidence["interactiveFailure"]=failure.ToString();File.WriteAllText("artifacts/windows-validation.json",JsonSerializer.Serialize(evidence,new JsonSerializerOptions{WriteIndented=true}));throw failure;}}
 File.WriteAllText("artifacts/windows-validation.json",JsonSerializer.Serialize(evidence,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine(JsonSerializer.Serialize(evidence));}
